'use strict';

// MODULES //

var uniform = require( '@stdlib/random/array/uniform' );
var bernoulli = require( '@stdlib/random/array/bernoulli' );
var array = require( '@stdlib/ndarray/array' );
var mskmin = require( './../lib' );


// MAIN //

var xbuf = uniform( 10, -50.0, 50.0, {
	'dtype': 'float64'
});
var mbuf = bernoulli( xbuf.length, 0.2, {
	'dtype': 'uint8'
});

// Create ndarrays:
var x = array( xbuf, {
	'shape': [ xbuf.length ]
});
var mask = array( mbuf, {
	'shape': [ mbuf.length ]
});

console.log( 'x:', x.data );
console.log( 'mask:', mask.data );

// Compute the minimum value:
var v = mskmin( [ x, mask ] );
console.log( 'mskmin:', v );

